namespace LWS.TruckWallball {
public enum WallballMode {PlayerAI,SharedKeyboard,SeparateControllers,KeyboardController,AIVsAI,SharedController,Custom}
[DefaultExecutionOrder(-100)]public sealed class WallballMatch:MonoBehaviour,ISportsWeatherLifecycle,ISportsScorePresentationSource {
 public string MatchId=>participantMatchId;
 public SportsScoreJournal ScoreJournal{get;private set;}
 public event Action<SportsScoreEvent> ScoreConfirmed;
 bool ISportsScorePresentationSource.ScoreRunning=>InMatch;
 bool ISportsScorePresentationSource.ScorePaused=>MenuOpen&&rules.Phase!=WallballPhase.Finished;
 bool ISportsScorePresentationSource.ScoreFinished=>rules.Phase==WallballPhase.Finished;
 bool ISportsScorePresentationSource.ScoreResultPage=>menus.Screen==WallballScreen.Result;
 bool ISportsScorePresentationSource.ScorePlayPage=>menus.Screen==WallballScreen.Play;
 Camera ISportsScorePresentationSource.ScoreCamera(int view)=>null;
 bool ISportsScorePresentationSource.TryReadViewportCard(int view,out int participant,out string score,out string detail){participant=-1;score=detail=null;return false;}
 void ConfirmTeamPoint(){int team=rules.PointWinner;bool finished=rules.Phase==WallballPhase.Finished;if(InMatch&&ScoreJournal!=null&&ScoreJournal.TryConfirmTeam("point:"+rules.Points,team==0?"blue":"orange",TeamName(team),HockeyPresentation.TeamColor(team),1,rules.Score[team],(finished?"MATCH WON · ":"RALLY WON · ")+rules.Reason,finished?SportsScoreTier.MatchChampion:SportsScoreTier.Major,"TEAM PTS",true,finished,out var receipt))ScoreConfirmed?.Invoke(receipt);}
 public string WeatherMatchId=>participantMatchId;
