 public bool WeatherPaused=>WeatherMatchActive&&MenuOpen;
 public bool WeatherAudible=>WeatherMatchActive&&!MenuOpen;
 public float WeatherSfx=>settings.sfx;
 LWS.TruckSports.SportsParticipantBinding participantBinding;string participantMatchId;
 public void RefreshParticipants(bool saveEdits=false){if(participantBinding==null||!participantBinding.Matches(players))participantBinding=new LWS.TruckSports.SportsParticipantBinding(players);else participantBinding.Refresh(saveEdits);}
 void RecordParticipants(string summary,int count){LWS.TruckSports.SportsParticipantRegistry.Record(participantMatchId,SetupKey,summary,players,count);}

 public const string SetupKey="TruckWallball.Setup.v1";
 public HockeyPlayer[] players=Defaults();
 public int blueSize=1,orangeSize=1;public int Count=>blueSize+orangeSize;public int Team(int slot)=>slot<blueSize?0:1;
 public int First(int team)=>team==0?0:blueSize;public int Size(int team)=>team==0?blueSize:orangeSize;
 public string TeamName(int team)=>team==0?"BLUE TEAM":"ORANGE TEAM";
 public int ServerSlot=>First(rules.Server)+(rules.Points%Size(rules.Server));
 public Vector3 contactHalfExtents=new Vector3(1.15f,1.3f,1.6f);public Vector3 contactCenter=new Vector3(0,.45f,.1f);
 public Key[] jumpKeys={Key.Space,Key.RightShift,Key.R,Key.U,Key.B,Key.Numpad0,Key.Digit0,Key.PageUp};public WallballMode mode;public WallballTruck[] trucks;public WallballAI[] agents;public WallballBall ball;public Collider floor,wall;public WallballMenus menus;public SportsSettings settings;public SportsFeedback feedback;public Renderer[] paint;public SportsTruckAppearanceHost[] appearanceHosts=Array.Empty<SportsTruckAppearanceHost>();
 public float halfWidth=8,courtLength=20;public readonly WallballRules rules=new WallballRules();public readonly SportsDeviceInput input=new SportsDeviceInput();
 public bool InMatch{get;private set;}public bool MenuOpen=>menus.Screen!=WallballScreen.Play;public int Revision{get;private set;}public int Replays{get;private set;}public int RallyShots{get;private set;}public int MaximumVolley{get;private set;}public bool ServeReleased{get;private set;}public int PhysicalReturns{get;private set;}public int LegalReturns{get;private set;}public string Notice{get;private set;}="FIRST TO 11 • WIN BY TWO";
 public readonly bool[] Armed=new bool[8];bool[] jumpHeld=new bool[8];int opening,lastEligible=-99,observedPoints;bool outgoingServe;float stalled;Material[] colors;readonly List<Material>[] cabPaint=new List<Material>[8];
 public bool Ready(int i){var p=players[i];return p.source==HockeySource.AI||p.source==HockeySource.Keyboard&&Keyboard.current!=null&&Keyboard.current.enabled||p.controller&&p.pad!=null&&p.pad.added&&p.pad.enabled;}
 public bool DevicesReady{get{if(!ValidateOwnership(out _))return false;for(int i=0;i<Count;i++)if(!Ready(i))return false;return true;}}public bool AllAI{get{for(int i=0;i<Count;i++)if(players[i].source!=HockeySource.AI)return false;return true;}}
 public static HockeyPlayer[] Defaults(){var source=LWS.TruckBowling.BowlingSetup.Defaults();var a=new HockeyPlayer[8];for(int i=0;i<8;i++)a[i]=new HockeyPlayer{name=source[i].name,color=source[i].color,source=i==0?HockeySource.Keyboard:HockeySource.AI,forward=source[i].forward,left=source[i].left,back=source[i].back,right=source[i].right};return a;}
 public void SetTeamSize(int team){if(InMatch)return;if(team==0)blueSize=blueSize%4+1;else orangeSize=orangeSize%4+1;SetActiveTrucks();Gate();Dirty();Save();}
 void SetActiveTrucks(){for(int i=0;i<trucks.Length;i++)trucks[i].gameObject.SetActive(i<Count);}
 public int Interceptor(int team){if(rules.Phase==WallballPhase.Serving)return team==rules.Server?ServerSlot:First(team);var p=ball.body.position+ball.body.linearVelocity*.35f;p.y=.36f;int best=First(team);float cost=float.PositiveInfinity;for(int i=First(team);i<First(team)+Size(team);i++){float d=(trucks[i].body.position-p).sqrMagnitude;if(d<cost){cost=d;best=i;}}return best;}
 public Vector3 ContactPoint(int i,Vector3 p){var t=trucks[i];var q=Quaternion.Inverse(t.body.rotation)*(p-t.body.position)-contactCenter;return t.body.position+t.body.rotation*(contactCenter+new Vector3(Mathf.Clamp(q.x,-contactHalfExtents.x,contactHalfExtents.x),Mathf.Clamp(q.y,-contactHalfExtents.y,contactHalfExtents.y),Mathf.Clamp(q.z,-contactHalfExtents.z,contactHalfExtents.z)));}

 public bool ValidateOwnership(out string reason){for(int i=0;i<Count;i++){var p=players[i];if(p.source==HockeySource.Keyboard){var keys=new[]{p.forward,p.left,p.back,p.right,jumpKeys[i]};for(int k=0;k<keys.Length;k++){if(keys[k]==Key.None||keys[k]==Key.Escape){reason="Assign driving/jump keys; Escape is reserved.";return false;}for(int j=0;j<k;j++)if(keys[k]==keys[j]){reason="Duplicate gameplay key.";return false;}for(int j=0;j<i;j++){var q=players[j];if(q.source==HockeySource.Keyboard&&(keys[k]==q.forward||keys[k]==q.left||keys[k]==q.back||keys[k]==q.right||keys[k]==jumpKeys[j])){reason="Keyboard sources overlap.";return false;}}}}else if(p.controller&&p.pad!=null)for(int j=0;j<i;j++){var q=players[j];if(q.controller&&q.pad==p.pad&&(q.source==p.source||q.source==HockeySource.WholeController||p.source==HockeySource.WholeController)){reason="One owner per whole pad or separate stick/trigger.";return false;}}}reason="";return true;}
 void Awake(){if(players.Length!=8){var old=players;players=Defaults();Array.Copy(old,players,Math.Min(old.Length,8));}for(int i=0;i<8;i++)cabPaint[i]=new List<Material>();for(int i=0;i<Count;i++)Physics.IgnoreCollision(trucks[i].shape,ball.shape);Freeze(true);colors=new Material[paint.Length];for(int i=0;i<paint.Length;i++){colors[i]=new Material(paint[i].sharedMaterial);paint[i].sharedMaterial=colors[i];}for(int i=0;i<Count;i++)foreach(var r in trucks[i].GetComponentsInChildren<MeshRenderer>())if(r.name=="Cab"&&r!=paint[i])foreach(var material in r.materials)cabPaint[i].Add(material);}
 void Start(){foreach(var t in trucks)t.CacheShapes();BindTruckPairs();Load();RefreshParticipants();SetActiveTrucks();Dirty();menus.Show(WallballScreen.Setup);}void OnEnable(){InputSystem.onDeviceChange+=DeviceChanged;}void OnDisable(){InputSystem.onDeviceChange-=DeviceChanged;feedback.StopAll();}void OnDestroy(){ScoreJournal?.Close();if(colors!=null)foreach(var c in colors)Destroy(c);foreach(var list in cabPaint)foreach(var c in list)Destroy(c);Time.timeScale=1;}
 public void Dirty(){Revision++;menus?.Dirty();}public void Gate(){foreach(var p in players)p.released=false;for(int i=0;i<Count;i++){trucks[i].Stop();jumpHeld[i]=JumpHeld(i);}menus?.Gate();}
 public void Configure(WallballMode selection){mode=selection;for(int i=0;i<Count;i++){var p=players[i];var old=p.source;p.source=selection==WallballMode.AIVsAI?HockeySource.AI:selection==WallballMode.SharedKeyboard?HockeySource.Keyboard:selection==WallballMode.SeparateControllers?HockeySource.WholeController:selection==WallballMode.SharedController?(i==0?HockeySource.LeftStick:HockeySource.RightStick):selection==WallballMode.KeyboardController?(i==0?HockeySource.Keyboard:HockeySource.WholeController):i==0?HockeySource.Keyboard:HockeySource.AI;if(old!=p.source)p.pad=null;}Gate();Dirty();Save();}
 public bool Assign(int i,Gamepad pad){if(i<0||i>=Count||!players[i].controller||pad==null||!pad.added||!pad.enabled)return false;var old=players[i].pad;players[i].pad=pad;if(!ValidateOwnership(out _)){players[i].pad=old;return false;}input.Forget(pad);Gate();Dirty();Save();return true;}
 public void Unassign(int i){players[i].pad=null;Gate();Dirty();}public void CycleSource(int i){mode=WallballMode.Custom;players[i].source=(HockeySource)(((int)players[i].source+1)%5);players[i].pad=null;Gate();Dirty();Save();}
 public Vector2 Drive(int i){var p=players[i];if(!Ready(i)||p.source==HockeySource.AI)return Vector2.zero;if(p.source==HockeySource.Keyboard)return new Vector2((SportsDeviceInput.KeyHeld(p.right)?1:0)-(SportsDeviceInput.KeyHeld(p.left)?1:0),(SportsDeviceInput.KeyHeld(p.forward)?1:0)-(SportsDeviceInput.KeyHeld(p.back)?1:0));if(p.source==HockeySource.LeftStick||p.source==HockeySource.RightStick){var v=p.source==HockeySource.LeftStick?p.pad.leftStick.ReadValue():p.pad.rightStick.ReadValue();return new Vector2(Mathf.Abs(v.x)<.16f?0:v.x,Mathf.Abs(v.y)<.16f?0:v.y);}var stick=p.pad.leftStick.ReadValue();float gas=p.pad.rightTrigger.ReadValue()-p.pad.leftTrigger.ReadValue();return new Vector2(Mathf.Abs(stick.x)<.16f?0:stick.x,Mathf.Abs(gas)<.1f?0:gas);}
 public bool JumpHeld(int i){if(!Ready(i))return false;var p=players[i];return p.source==HockeySource.Keyboard?SportsDeviceInput.KeyHeld(jumpKeys[i]):p.source==HockeySource.LeftStick?p.pad.leftTrigger.ReadValue()>.5f:p.source==HockeySource.RightStick?p.pad.rightTrigger.ReadValue()>.5f:p.source==HockeySource.WholeController&&p.pad.buttonSouth.isPressed;}
 public bool Neutral(int i)=>Ready(i)&&(players[i].source==HockeySource.AI||Drive(i).sqrMagnitude<.01f&&!JumpHeld(i)&&(!players[i].controller||!players[i].pad.startButton.isPressed&&!players[i].pad.buttonSouth.isPressed));
 public string Controls(int i){var p=players[i];return p.source==HockeySource.AI?"AI • "+p.difficulty:p.source==HockeySource.Keyboard?p.forward+"/"+p.left+"/"+p.back+"/"+p.right+" • "+jumpKeys[i]+" JUMP":p.source==HockeySource.LeftStick?"LEFT STICK drives • LT JUMP":p.source==HockeySource.RightStick?"RIGHT STICK drives • RT JUMP":"LEFT STICK steers • RT/LT drive/brake • SOUTH JUMP";}
 void DeviceChanged(InputDevice device,InputDeviceChange change){if(LWS.TruckSports.SportsFocusPolicy.Suspended(device,change))return;Dirty();foreach(var p in players)if(p.controller&&p.pad==device){input.Forget((Gamepad)device);Gate();if(InMatch&&rules.Phase!=WallballPhase.Finished&&(change==InputDeviceChange.Removed||change==InputDeviceChange.Disconnected||change==InputDeviceChange.Disabled))Pause(true);break;}}
 public bool StartMatch(bool rematch=false){if(!DevicesReady){menus.Show(WallballScreen.Join);return false;}opening=rematch?1-opening:0;MaximumVolley=0;SetActiveTrucks();Save();ScoreJournal?.Close();participantMatchId=System.Guid.NewGuid().ToString("N");ScoreJournal=new SportsScoreJournal(gameObject.scene.name,participantMatchId);InMatch=true;Replays=PhysicalReturns=LegalReturns=observedPoints=0;rules.Start(opening);ResetServe();Gate();menus.Show(WallballScreen.Play);Time.timeScale=1;Notice=TeamName(opening)+" opens • FIRST TO 11, WIN BY TWO";return true;}
 void Freeze(bool value){for(int ti=0;ti<Count;ti++){var t=trucks[ti];if(value&&!t.body.isKinematic)t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.isKinematic=value;t.Stop();foreach(var w in t.wheels)w.enabled=!value;if(!value){foreach(var w in t.wheels)w.WakeFromSleep();t.CacheShapes();}}if(value&&!ball.body.isKinematic)ball.body.linearVelocity=ball.body.angularVelocity=Vector3.zero;ball.body.isKinematic=value;if(!value)BindTruckPairs();}
 public void ResetServe(){ServeReleased=false;RallyShots=0;Freeze(true);for(int i=0;i<Count&&i<appearanceHosts.Length;i++)if(appearanceHosts[i]!=null)appearanceHosts[i].Prepare(players[i].participantId,players[i].color);float x=rules.Server==0?-3:3;ball.body.position=new Vector3(x,.55f,-5.7f);ball.body.rotation=Quaternion.identity;for(int i=0;i<Count;i++){int local=i-First(Team(i));bool serving=Team(i)==rules.Server;var spawn=i==ServerSlot?new Vector3(x,.36f,-8):i==First(1-rules.Server)?new Vector3(x,.36f,-11.4f):new Vector3(-5.25f+local*3.5f,.36f,serving?-14.8f:-18.2f);trucks[i].ResetBody(spawn);colors[i].color=players[i].color;foreach(var material in cabPaint[i])material.color=players[i].color;}foreach(var a in agents)a.ResetPlan();ball.ClearContacts();lastEligible=-99;stalled=0;ArmContacts();feedback.StopAll();Physics.SyncTransforms();}
 public void Pause(bool disconnected=false){if(!InMatch||rules.Phase==WallballPhase.Finished)return;rules.Pause();Time.timeScale=0;Gate();feedback.StopAll();menus.Show(disconnected?WallballScreen.Disconnect:WallballScreen.Pause);}
 public void Resume(){if(!DevicesReady){Pause(true);return;}rules.Resume();Time.timeScale=1;Gate();menus.Show(WallballScreen.Play);}public void ChangeSetup(){ScoreJournal?.Close();InMatch=false;Time.timeScale=1;Freeze(true);feedback.StopAll();menus.Show(WallballScreen.Setup);}
 public void Replay(string reason){if(!rules.Active)return;Replays++;rules.Replay();ResetServe();Notice="RALLY REPLAY • SCORE UNCHANGED • "+reason;Debug.Log("WB_NEUTRAL_REPLAY "+reason);}
 public void RecoverTruck(int i){for(int k=0;k<4;k++){var p=new Vector3((i==0?-1:1)*(3+k%2*2),.36f,-12-k/2*3);if(Vector3.Distance(p,ball.body.position)<2.5f)continue;trucks[i].ResetBody(p);agents[i].ResetPlan();Notice=players[i].name+" recovered • Rally and score retained";return;}}
 // Eligibility changes only collision ownership. Neither movement nor held-input state is gated.
 public void BindTruckPairs(){for(int i=0;i<trucks.Length;i++){var aa=trucks[i].CollisionShapes??new[]{(Collider)trucks[i].shape};foreach(var a in aa){if(a==null)continue;Physics.IgnoreCollision(a,ball.shape);for(int j=i+1;j<trucks.Length;j++)foreach(var b in trucks[j].CollisionShapes??new[]{(Collider)trucks[j].shape})if(b!=null)Physics.IgnoreCollision(a,b);}}}
 public void ArmContacts(){int eligible=rules.Active?rules.Eligible:-1;if(eligible!=lastEligible){Array.Clear(Armed,0,Armed.Length);lastEligible=eligible;}for(int i=0;i<Count;i++)if(Team(i)==eligible&&!Armed[i]&&Vector3.Distance(ContactPoint(i,ball.body.position),ball.body.position)>ball.radius+.09f)Armed[i]=true;}
 void ContactVolume(){int best=-1;float strongest=0;Vector3 bestNormal=Vector3.zero,bestRelative=Vector3.zero;for(int i=0;i<Count;i++){if(!Armed[i]||Team(i)!=rules.Eligible)continue;var point=ContactPoint(i,ball.body.position);var n=ball.body.position-point;if(n.sqrMagnitude>ball.radius*ball.radius)continue;if(n.sqrMagnitude<.001f)n=ball.body.position-(trucks[i].body.position+trucks[i].body.rotation*contactCenter);n.Normalize();var relative=ball.body.linearVelocity-trucks[i].body.GetPointVelocity(point);float closing=-Vector3.Dot(relative,n);if(closing<=.15f)continue;if(Physics.Linecast(trucks[i].body.position+Vector3.up*.55f,ball.body.position,out var hit,1,QueryTriggerInteraction.Ignore)&&hit.collider==wall)continue;if(closing>strongest){strongest=closing;best=i;bestNormal=n;bestRelative=relative;}}if(best>=0&&Strike(best,bestNormal,bestRelative)){ball.RecordTruckContact(strongest);}}
 public bool Strike(int slot,Vector3 normal,Vector3 relative){if(!Armed[slot]||rules.Eligible!=Team(slot)||!rules.Active)return false;bool serve=rules.Phase==WallballPhase.Serving;if(!rules.Strike(Team(slot)))return false;outgoingServe=serve;RallyShots++;MaximumVolley=Math.Max(MaximumVolley,RallyShots);trucks[slot].RecordHit();if(!serve)PhysicalReturns++;stalled=0;
  // Ball-only envelope is the sole truck contact authority; native truck-ball pairs are ignored.
  // Reflect actual relative approach about the contact normal, never toward a scoring target.
  var planar=new Vector3(normal.x,0,normal.z);if(planar.sqrMagnitude<.04f)planar=trucks[slot].transform.forward;else planar.Normalize();float closing=Mathf.Max(0,-Vector3.Dot(relative,normal));var v=trucks[slot].body.linearVelocity+Vector3.Reflect(new Vector3(relative.x,0,relative.z),planar)*.78f+planar*Mathf.Clamp(closing*.3f,.6f,2.5f);v.y=Mathf.Clamp(v.y,5.8f,7.2f);ball.body.linearVelocity=Vector3.ClampMagnitude(v,ball.maxSpeed);Array.Clear(Armed,0,Armed.Length);ArmContacts();Notice=players[slot].name+" hit • Reach the wall before the floor";Pulse(slot,.1f,.08f);Debug.Log("WB_PHYSICAL_STRIKE slot="+slot+" shot="+rules.Shots+" serve="+serve+" velocity="+ball.body.linearVelocity);return true;}
 public void Wall(bool valid){int before=rules.LegalWalls;rules.Wall(valid);if(rules.LegalWalls>before&&!outgoingServe)LegalReturns++;ArmContacts();if(rules.Phase==WallballPhase.Receiving)Notice=TeamName(rules.Eligible)+" TO HIT • Volley or one bounce";ResolvePoint();}
 public void Floor(){var p=ball.body.position;if(Mathf.Abs(p.x)>halfWidth||p.z< -courtLength)rules.Out();else rules.Floor();if(rules.Phase==WallballPhase.Receiving&&rules.Bounces==1)Notice="FIRST BOUNCE • "+TeamName(rules.Eligible)+" TO HIT";ResolvePoint();}
 public void ResolvePoint(){if(rules.Points==observedPoints)return;observedPoints=rules.Points;Freeze(true);ArmContacts();Notice=rules.Reason+" • POINT TO "+TeamName(rules.PointWinner);ConfirmTeamPoint();feedback.Play(6,0,true);Debug.Log("WB_POINT "+Notice+" score="+rules.Score[0]+":"+rules.Score[1]);if(rules.Phase==WallballPhase.Finished){ScoreJournal?.Close();RecordParticipants("Team score: "+rules.Score[0]+":"+rules.Score[1],Count);menus.Show(WallballScreen.Result);feedback.StopMotors();menus.Celebrate();feedback.Play(7,0,true);Time.timeScale=0;}}
 public void Pulse(int i,float strength,float duration){feedback.Pulse(players[i].controller?players[i].pad:null,strength,duration);}
 void Update(){input.Sample();if(menus.Screen==WallballScreen.Join||menus.Screen==WallballScreen.Disconnect)foreach(var pad in Gamepad.all)if(input.Down(pad,2))for(int i=0;i<Count;i++)if(players[i].controller&&!Ready(i)&&Assign(i,pad)){if(players[i].source==HockeySource.WholeController)break;}
  bool pause=SportsDeviceInput.KeyDown(Key.Escape);foreach(var p in players)if(p.controller&&input.Down(p.pad,4))pause=true;if(AllAI)foreach(var pad in Gamepad.all)pause|=input.Down(pad,4);if(pause){if(menus.Screen==WallballScreen.Play)Pause();else menus.Back();return;}if(!InMatch||MenuOpen)return;
  for(int i=0;i<Count;i++){if(players[i].source==HockeySource.AI)continue;if(!Ready(i)){Pause(true);return;}bool jump=JumpHeld(i),pressed=jump&&!jumpHeld[i];jumpHeld[i]=jump;if(!players[i].released){trucks[i].Stop();if(Neutral(i))players[i].released=true;continue;}if(rules.Active){var drive=Drive(i);drive.x*=settings.sensitivity;trucks[i].Control(drive,pressed);}}}
 void FixedUpdate(){if(!InMatch||MenuOpen)return;var before=rules.Phase;rules.Tick(Time.fixedDeltaTime);ResolvePoint();if(before==WallballPhase.Point&&rules.Phase==WallballPhase.Countdown){ResetServe();Notice=TeamName(rules.Server)+" serves";}if(rules.Active&&!ServeReleased){ServeReleased=true;Freeze(false);ball.ClearContacts();Notice=TeamName(rules.Server)+" TO SERVE • 25 SECONDS";feedback.Play(0,0,true);}
  if(!rules.Active)return;ArmContacts();ContactVolume();var p=ball.body.position;if(float.IsNaN(p.x)||p.y< -1){Replay("Ball simulation recovered");return;}if(Mathf.Abs(p.x)>halfWidth+ball.radius||p.z< -courtLength-ball.radius||p.y>9||p.z>.6f&&(Mathf.Abs(p.x)>halfWidth-.2f||p.y>7.5f)){rules.Out();ResolvePoint();return;}if(p.z>.6f){Replay("Missing wall contact");return;}
  if(rules.Phase!=WallballPhase.Serving){stalled=ball.body.linearVelocity.sqrMagnitude<.01f?stalled+Time.fixedDeltaTime:0;if(stalled>4){Replay("Ball stopped without a resolving contact");return;}}for(int i=0;i<Count;i++)if(trucks[i].body.position.y< -2||Mathf.Abs(trucks[i].body.position.x)>halfWidth+2||trucks[i].body.position.z< -courtLength-2)RecoverTruck(i);}
 [Serializable]sealed class Saved{public WallballMode mode;public int blueSize=1,orangeSize=1;public Slot[] slots;}[Serializable]sealed class Slot{public string name,participantId;public Color color;public HockeySource source;public HockeyDifficulty difficulty;public int pad;public Key jump;}
 public void Save(){RefreshParticipants(true);var s=new Saved{mode=mode,blueSize=blueSize,orangeSize=orangeSize,slots=new Slot[Count]};for(int i=0;i<Count;i++){var p=players[i];s.slots[i]=new Slot{participantId=p.participantId,name=p.name,color=p.color,source=p.source,difficulty=p.difficulty,pad=p.pad?.deviceId??-1,jump=jumpKeys[i]};}LWS.TruckSports.SportsPrefs.SetString(SetupKey,JsonUtility.ToJson(s));LWS.TruckSports.SportsPrefs.Save();}
 void Load(){try{if(!LWS.TruckSports.SportsPrefs.HasKey(SetupKey))return;var s=JsonUtility.FromJson<Saved>(LWS.TruckSports.SportsPrefs.GetString(SetupKey));if(s?.slots==null||s.slots.Length<2||s.slots.Length>8)return;mode=s.mode;blueSize=Mathf.Clamp(s.blueSize,1,4);orangeSize=Mathf.Clamp(s.orangeSize,1,4);for(int i=0;i<Math.Min(s.slots.Length,Count);i++){var p=players[i];var a=s.slots[i];p.name=string.IsNullOrWhiteSpace(a.name)?"Player "+(i+1):a.name;p.participantId=a.participantId;p.color=a.color;p.source=a.source;p.difficulty=a.difficulty;p.pad=InputSystem.GetDeviceById(a.pad) as Gamepad;if(a.jump!=Key.None)jumpKeys[i]=a.jump;}}catch(Exception){Debug.LogWarning("Wallball setup invalid; defaults retained.");}}
}
}
